// Checkout handler with paidEvent logging
const { logPaidEvent } = require('./revenueTracker');

module.exports = async function handleCheckout(req, res) {
  try {
    const { userId, plan, amount, currency } = req.body;
    // Simulate payment processing
    const paymentSuccess = true; // Replace with actual payment gateway call
    if (paymentSuccess) {
      await logPaidEvent({ userId, plan, amount, currency });
      res.status(200).json({ status: 'success', paidEvent: true });
    } else {
      res.status(400).json({ status: 'failed', paidEvent: false });
    }
  } catch (err) {
    console.error('Checkout error:', err);
    res.status(500).json({ status: 'error', message: err.message });
  }
};
